3	import (
4		"errors"
5		"fmt"
6		"os"
7		"strings"
8		"testing"
9	)
10	
11	// These tests pin down the consolidation of message-state recovery: a plain
12	// result entry (kindResult) and a compacted snapshot entry (kindState) must
13	// judge the same message status with the same rules — waiting schedule,
14	// nonce consumption and terminal field hygiene — while keeping their own
15	// acceptance conditions (results are incremental: non-terminal target,
16	// attempts exactly +1, no backwards processing time; snapshots are full
17	// current states after >=1 attempts and may restore a larger attempt count
18	// directly, but never twice for one message). Corrupt opens must still fail
19	// with ErrCorrupt, leave queue.log byte-for-byte untouched, and keep the
20	// record category ("result"/"state"/"entry"), the message id and the reason
21	// recognizable in the error text.
22	
23	// waitingRecoveryBase is the entries before a waiting status record: a
24	// registered but header-less source and one pending message.
25	func waitingRecoveryBase() []*logEntry {
26		return []*logEntry{
27			{T: kindSource, Chain: "a"},
28			{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 7, ProofAt: 100},
29		}
30	}
31	
32	// waitingRecoveryRecord is a valid waiting status record at now=1000 with one
33	// attempt, retry at 2000. Callers mutate copies.
34	func waitingRecoveryRecord(kind string) *logEntry {
35		return &logEntry{
36			T: kind, Now: 1000, ID: "w", Status: StatusWaiting,
37			Reason:   "waiting for trusted header covering height 100 (current 0)",
38			Attempts: 1, NextRetry: 2000,
39		}
40	}
41	
42	// successRecoveryBase is the entries before a success status record: a
43	// registered source with a header covering the proof height and one pending
44	// message.
45	func successRecoveryBase() []*logEntry {
46		return []*logEntry{
47			{T: kindSource, Chain: "a"},
48			{T: kindHeader, Chain: "a", Height: 100, Root: "0x100", Trusted: true},
49			{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, ProofAt: 10},
50		}
51	}
52	
53	// successRecoveryRecord is a valid success record consuming its own triple.
54	func successRecoveryRecord(kind string) *logEntry {
55		return &logEntry{
56			T: kind, Now: 1000, ID: "m", Status: StatusSuccess,
57			Reason:   "delivered; proof verified by trusted header at height 100",
58			Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
59		}
60	}
61	
62	// terminalRecoveryBase is one pending message "t" that a terminal record
63	// settles as replay.
64	func terminalRecoveryBase() []*logEntry {
65		return []*logEntry{
66			{T: kindSource, Chain: "a"},
67			{T: kindSubmit, Seq: 0, ID: "t", From: "a", To: "b", Nonce: 1, ProofAt: 10},
68		}
69	}
70	
71	func terminalRecoveryRecord(kind string) *logEntry {
72		return &logEntry{
73			T: kind, Now: 1000, ID: "t", Status: StatusReplay,
74			Reason: "nonce combination already consumed by message z", Attempts: 1,
75		}
76	}
77	
78	// assertRecoveryCorrupt writes the entries as a V1 log, requires Open to fail
79	// with ErrCorrupt and no usable queue, requires every wanted substring to
80	// appear in the error, and requires the log bytes to stay untouched.
81	func assertRecoveryCorrupt(t *testing.T, entries []*logEntry, want ...string) {
82		t.Helper()
83		dir := t.TempDir()
84		path := writeLegacyLog(t, dir, entries...)
85		before, err := os.ReadFile(path)
86		if err != nil {
87			t.Fatal(err)
88		}
89		q, err := Open(dir)
90		if !errors.Is(err, ErrCorrupt) {
91			if q != nil {
92				q.Close()
93			}
94			t.Fatalf("want ErrCorrupt, got %v (queue=%v)", err, q != nil)
95		}
96		if q != nil {
97			q.Close()
98			t.Fatalf("corrupt open must not return a usable queue")
99		}
100		msg := err.Error()
101		for _, w := range want {
102			if !strings.Contains(msg, w) {
103				t.Fatalf("error %q does not identify %q", msg, w)
104			}
105		}
106		after, err := os.ReadFile(path)
107		if err != nil {
108			t.Fatal(err)
109		}
110		if string(after) != string(before) {
111			t.Fatalf("corrupt log was modified: %d -> %d bytes", len(before), len(after))
112		}
113	}
114	
115	// TestSharedRecoveryRulesRejectSameShapes verifies that every per-status rule
116	// rejects a result entry and a compacted state entry identically: the same
117	// bad shape is corrupt either way, and the error keeps the category and the
118	// message id recognizable.
119	func TestSharedRecoveryRulesRejectSameShapes(t *testing.T) {
120		cases := []struct {
121			name    string
122			entries func(kind string) []*logEntry
123			want    func(label, successNoun string) []string
124		}{
125			{
126				name: "unknown status",
127				entries: func(kind string) []*logEntry {
128					r := waitingRecoveryRecord(kind)
129					r.Status = "bogus"
130					return append(waitingRecoveryBase(), r)
131				},
132				want: func(label, _ string) []string {
133					return []string{fmt.Sprintf("bad %s status", label), `"bogus"`, `"w"`}
134				},
135			},
136			{
137				name: "pending status",
138				entries: func(kind string) []*logEntry {
139					r := waitingRecoveryRecord(kind)
140					r.Status = StatusPending
141					return append(waitingRecoveryBase(), r)
142				},
143				want: func(label, _ string) []string {
144					return []string{fmt.Sprintf("bad %s status", label), StatusPending, `"w"`}
145				},
146			},
147			{
148				name: "waiting wrong retry schedule",
149				entries: func(kind string) []*logEntry {
150					r := waitingRecoveryRecord(kind)
151					r.NextRetry = 4242
152					return append(waitingRecoveryBase(), r)
153				},
154				want: func(label, _ string) []string {
155					return []string{fmt.Sprintf("waiting %s has wrong retry schedule", label), `"w"`}
156				},
157			},
158			{
159				name: "waiting carries nonce consumption",
160				entries: func(kind string) []*logEntry {
161					r := waitingRecoveryRecord(kind)
162					r.ConsumeBy = "w"
163					return append(waitingRecoveryBase(), r)
164				},
165				want: func(label, _ string) []string {
166					return []string{fmt.Sprintf("waiting %s", label), "carries nonce consumption fields", `"w"`}
167				},
168			},
169			{
170				name: "success carries retry time",
171				entries: func(kind string) []*logEntry {
172					r := successRecoveryRecord(kind)
173					r.NextRetry = 7
174					return append(successRecoveryBase(), r)
175				},
176				want: func(_, successNoun string) []string {
177					return []string{fmt.Sprintf("success %s for %q carries retry time", successNoun, "m")}
178				},
179			},
180			{
181				name: "success without nonce consumption",
182				entries: func(kind string) []*logEntry {
183					r := successRecoveryRecord(kind)
184					r.ConsumeFrom, r.ConsumeTo, r.ConsumeNonce = "", "", 0
185					return append(successRecoveryBase(), r)
186				},
187				want: func(_, _ string) []string {
188					return []string{"success entry", "carries no nonce consumption", `"m"`}
189				},
190			},
191			{
192				name: "success mismatched triple",
193				entries: func(kind string) []*logEntry {
194					r := successRecoveryRecord(kind)
195					r.ConsumeNonce = 9
196					return append(successRecoveryBase(), r)
197				},
198				want: func(_, _ string) []string {
199					return []string{"success entry", "mismatched nonce consumption", `"m"`}
200				},
201			},
202			{
203				name: "success attributed to another message",
204				entries: func(kind string) []*logEntry {
205					r := successRecoveryRecord(kind)
206					r.ConsumeBy = "x"
207					return append(successRecoveryBase(), r)
208				},
209				want: func(_, _ string) []string {
210					return []string{"success entry", "marked consumed by", `"x"`, `"m"`}
211				},
212			},
213			{
214				name: "same triple consumed twice",
215				entries: func(kind string) []*logEntry {
216					base := []*logEntry{
217						{T: kindSource, Chain: "a"},
218						{T: kindHeader, Chain: "a", Height: 100, Root: "0x100", Trusted: true},
219						{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, ProofAt: 10},
220						{T: kindSubmit, Seq: 1, ID: "n", From: "a", To: "b", Nonce: 1, ProofAt: 10},
221					}
222					first := &logEntry{
223						T: kind, Now: 1000, ID: "m", Status: StatusSuccess, Reason: "ok", Attempts: 1,
224						ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
225					}
226					second := &logEntry{
227						T: kind, Now: 1000, ID: "n", Status: StatusSuccess, Reason: "ok", Attempts: 1,
228						ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "n",
229					}
230					return append(base, first, second)
231				},
232				want: func(_, _ string) []string {
233					return []string{"already consumed by", `"m"`, `"n"`}
234				},
235			},
236			{
237				name: "terminal carries retry time",
238				entries: func(kind string) []*logEntry {
239					r := terminalRecoveryRecord(kind)
240					r.NextRetry = 9
241					return append(terminalRecoveryBase(), r)
242				},
243				want: func(_, successNoun string) []string {
244					return []string{fmt.Sprintf("terminal %s for %q carries scheduling/consume fields", successNoun, "t")}
245				},
246			},
247			{
248				name: "terminal carries consumption",
249				entries: func(kind string) []*logEntry {
250					r := terminalRecoveryRecord(kind)
251					r.ConsumeNonce = 1
252					return append(terminalRecoveryBase(), r)
253				},
254				want: func(_, successNoun string) []string {
255					return []string{fmt.Sprintf("terminal %s for %q carries scheduling/consume fields", successNoun, "t")}
256				},
257			},
258		}
259	
260		for _, kind := range []struct {
261			t           string
262			label       string
263			successNoun string
264		}{
265			{kindResult, "result", "entry"},
266			{kindState, "state", "state"},
267		} {
