1	package relayproof
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// TestAdvanceMidSaveFailureKeepsCommittedResults pins the boundary around a
10	// result save failing partway through one Advance, going through the unified
11	// applyOutcome path:
12	//
13	//   - the failing result returns the wrapped storage error;
14	//   - the failed message keeps its previous status, reason, attempts,
15	//     processing time and retry schedule, and its nonce is not consumed;
16	//   - results already acknowledged earlier in the same advance stay in force;
17	//   - the queue instance keeps refusing further writes, while queries still
18	//     reflect everything that did take effect.
19	func TestAdvanceMidSaveFailureKeepsCommittedResults(t *testing.T) {
20		q, _ := openTempQueue(t)
21		defer q.Close()
22		if err := q.RegisterSource("a"); err != nil {
23			t.Fatal(err)
24		}
25		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true}); err != nil {
26			t.Fatal(err)
27		}
28		if _, err := q.Submit(env("m1", "a", "b", 1, 10, 0)); err != nil {
29			t.Fatal(err)
30		}
31		if _, err := q.Submit(env("m2", "a", "b", 2, 10, 0)); err != nil {
32			t.Fatal(err)
33		}
34	
35		// Appends so far: source, header, submit m1, submit m2 (4). The advance
36		// saves m1's success as call 5 (committed) and must fail on m2 at call 6.
37		q.store.injectErr = errors.New("disk on fire")
38		q.store.injectErrOnCall = 6
39	
40		_, err := q.Advance(1000)
41		if !errors.Is(err, ErrStorage) {
42			t.Fatalf("want ErrStorage from the failed save, got %v", err)
43		}
44		if !strings.Contains(err.Error(), "deliver") {
45			t.Fatalf("error must keep the deliver op label, got %v", err)
46		}
47	
48		// m1 was acknowledged before the failure and stays delivered, nonce
49		// consumed.
50		if r := statusOf(t, q, "m1"); r.Status != StatusSuccess || r.Attempts != 1 {
51			t.Fatalf("committed m1 must survive the later failure: %+v", r)
52		}
53		if winner := q.consumed[newConsumeToken("a", "b", 1)]; winner != "m1" {
54			t.Fatalf("m1 consumption lost: %q", winner)
55		}
56	
57		// m2's save never acknowledged: it keeps its pre-advance pending state and
58		// does not consume its nonce.
59		if r := statusOf(t, q, "m2"); r.Status != StatusPending || r.Attempts != 0 || r.NextRetry != 0 {
60			t.Fatalf("failed m2 must keep its prior state: %+v", r)
61		}
62		if _, taken := q.consumed[newConsumeToken("a", "b", 2)]; taken {
63			t.Fatal("failed m2 must not consume its nonce")
64		}
65		if q.now != 0 {
66			t.Fatalf("processing time must not advance past the failed save: %d", q.now)
67		}
68	
69		// The instance keeps rejecting writes, and reopening later drops only the
70		// unacknowledged torn tail while keeping m1.
71		if err := q.RegisterSource("c"); !errors.Is(err, ErrStorage) {
72			t.Fatalf("broken queue must refuse writes, got %v", err)
73		}
74		if r := statusOf(t, q, "m1"); r.Status != StatusSuccess {
75			t.Fatalf("query must still reflect committed m1: %+v", r)
76		}
77		if r := statusOf(t, q, "m2"); r.Status != StatusPending {
78			t.Fatalf("query must still show untouched m2: %+v", r)
79		}
80	}
81	
82	// A failed waiting save leaves the message on its previous backoff schedule
83	// and attempt count, while an earlier result in the same advance is kept.
84	func TestAdvanceWaitingSaveFailureKeepsPriorSchedule(t *testing.T) {
85		q, _ := openTempQueue(t)
86		defer q.Close()
87		if err := q.RegisterSource("a"); err != nil {
88			t.Fatal(err)
89		}
90		if _, err := q.Submit(env("m1", "a", "b", 1, 10, 0)); err != nil {
91			t.Fatal(err)
92		}
93		// First advance: no header -> waiting, retry at 2000, one attempt.
94		if _, err := q.Advance(1000); err != nil {
95			t.Fatal(err)
96		}
97		if r := statusOf(t, q, "m1"); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 2000 {
98			t.Fatalf("setup: want waiting retry=2000 attempts=1, got %+v", r)
99		}
100	
101		// Appends so far: source(1), submit(2); within the first advance the
102		// waiting result is appended at call 3 and the advance checkpoint at 4. On
103		// the next advance the waiting re-save is call 5: make it fail.
104		q.store.injectErr = errors.New("disk on fire")
105		q.store.injectErrOnCall = 5
106		_, err := q.Advance(2000)
107		if !errors.Is(err, ErrStorage) {
108			t.Fatalf("want ErrStorage, got %v", err)
109		}
110		if !strings.Contains(err.Error(), "schedule retry") {
111			t.Fatalf("waiting failure must keep the schedule retry op label, got %v", err)
112		}
113		// Prior schedule and attempt count are intact; LastProcAt stays 1000.
114		if r := statusOf(t, q, "m1"); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 2000 {
115			t.Fatalf("failed waiting save must keep prior schedule: %+v", r)
116		}
117		if got, ok := q.Query("m1"); !ok || got.Status != StatusWaiting {
118			t.Fatalf("query after failure must still show waiting: %+v ok=%v", got, ok)
119		}
120	}
