10	// Regression tests for retry scheduling at the int64 ceiling. Processing
11	// times are caller-supplied non-negative Unix milliseconds up to
12	// math.MaxInt64; the retry instant (processing time + backoff) must saturate
13	// at that ceiling rather than wrap to a negative, zero or earlier instant.
14	// Every observation goes through the public Advance/Query surface.
15	
16	const ceiling = int64(math.MaxInt64)
