18	// waitingAtCeilingSetup registers a source with a trusted header just short
19	// of the proof height and submits one never-expiring message (proof height
20	// 100, current trusted height 99), so every processing ends up waiting.
21	func waitingAtCeilingSetup(t *testing.T, q *Queue, id string) {
22		t.Helper()
23		if err := q.RegisterSource("a"); err != nil {
24			t.Fatal(err)
25		}
26		if err := q.UpsertHeader(Header{Chain: "a", Height: 99, Root: "0x99", Trusted: true}); err != nil {
27			t.Fatal(err)
28		}
29		if _, err := q.Submit(env(id, "a", "b", 7, 100, 0)); err != nil {
30			t.Fatal(err)
31		}
32	}
