63	// Unit checks for the due predicate at the ceiling.
64	func TestRetryDueAtCeiling(t *testing.T) {
65		normal := &Record{Status: StatusWaiting, Attempts: 1, LastProcAt: 1000, NextRetry: 2000}
66		if retryDue(normal, 1999) {
67			t.Fatal("1999 is before retry 2000: not due")
68		}
69		if !retryDue(normal, 2000) {
70			t.Fatal("2000 reaches retry 2000: due")
71		}
72		if retryDue(normal, 1000) {
73			t.Fatal("equal-time re-advance at the processing instant must not reprocess")
74		}
75	
76		// Saturated schedule, processed before the ceiling: reaching the ceiling
77		// is a distinct, later instant and the retry is due.
78		stuck := &Record{Status: StatusWaiting, Attempts: 1, LastProcAt: ceiling - 500, NextRetry: ceiling}
79		if !retryDue(stuck, ceiling) {
80			t.Fatal("retry at the ceiling must be due when last processed earlier")
81		}
82	
83		// Already processed at the ceiling: the only legal later instant does not
84		// exist, so equal time is never due again.
85		atCeiling := &Record{Status: StatusWaiting, Attempts: 1, LastProcAt: ceiling, NextRetry: ceiling}
86		if retryDue(atCeiling, ceiling) {
87			t.Fatal("message already processed at the ceiling must not be due at the same time")
88		}
89	}
