91	// A never-expiring message first processed 500ms before the ceiling cannot
92	// fit its 1s backoff: the retry saturates to the ceiling, never a negative
93	// number. Advancing at instants before the ceiling changes nothing.
94	func TestWaitingRetrySaturatesAtCeiling(t *testing.T) {
95		q, _ := openTempQueue(t)
96		defer q.Close()
97		waitingAtCeilingSetup(t, q, "m1")
98	
99		first := ceiling - 500
100		rep, err := q.Advance(first)
101		if err != nil {
102			t.Fatal(err)
103		}
104		res, ok := resultFor(rep, "m1")
105		if !ok || res.Status != StatusWaiting {
106			t.Fatalf("first advance: want one waiting result, got %+v", rep.Results)
107		}
108		r := statusOf(t, q, "m1")
109		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != ceiling || r.Msg.ExpiresAt != 0 {
110			t.Fatalf("want waiting attempts=1 retry=ceiling no-expiry, got %+v", r)
111		}
112		if r.NextRetry <= 0 || r.NextRetry < first {
113			t.Fatalf("retry %d wrapped non-positive or before processing %d", r.NextRetry, first)
114		}
115	
116		// Advancing at later instants still below the ceiling changes nothing and
117		// reports no result.
118		for _, now := range []int64{ceiling - 400, ceiling - 1} {
119			rep, err := q.Advance(now)
120			if err != nil {
121				t.Fatal(err)
122			}
123			if _, ok := resultFor(rep, "m1"); ok {
124				t.Fatalf("advance at %d before the ceiling must not reprocess m1: %+v", now, rep.Results)
125			}
126			r = statusOf(t, q, "m1")
127			if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != ceiling {
128				t.Fatalf("advance at %d changed the waiting record: %+v", now, r)
129			}
130		}
131	}
