133	// When the retry reaches the ceiling, a covering trusted header lets the
134	// message succeed by the normal rules, consuming the nonce on its second
135	// attempt.
136	func TestCeilingRetryWithCoveringHeaderSucceeds(t *testing.T) {
137		q, _ := openTempQueue(t)
138		defer q.Close()
139		waitingAtCeilingSetup(t, q, "m1")
140	
141		if _, err := q.Advance(ceiling - 500); err != nil {
142			t.Fatal(err)
143		}
144		// The header covers the proof height before the retry, but does not
145		// bypass it; only the advance to the ceiling delivers.
146		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
147			t.Fatal(err)
148		}
149		if _, err := q.Advance(ceiling - 1); err != nil {
150			t.Fatal(err)
151		}
152		r0 := statusOf(t, q, "m1")
153		if r0.Status != StatusWaiting || r0.Attempts != 1 || r0.NextRetry != ceiling {
154			t.Fatalf("pre-ceiling advance must not deliver: %+v", r0)
155		}
156	
157		rep, err := q.Advance(ceiling)
158		if err != nil {
159			t.Fatal(err)
160		}
161		res, ok := resultFor(rep, "m1")
162		if !ok || res.Status != StatusSuccess {
163			t.Fatalf("ceiling retry with coverage: want success, got %+v", rep.Results)
164		}
165		r := statusOf(t, q, "m1")
166		if r.Status != StatusSuccess || r.Attempts != 2 || r.NextRetry != 0 {
167			t.Fatalf("want success attempts=2 no retry, got %+v", r)
168		}
169		if got := q.consumed[newConsumeToken("a", "b", 7)]; got != "m1" {
170			t.Fatalf("nonce not consumed by m1: %q", got)
171		}
172		// A terminal record at the ceiling survives equal-time re-advances.
173		rep, err = q.Advance(ceiling)
174		if err != nil {
175			t.Fatal(err)
176		}
177		if len(rep.Results) != 0 {
178			t.Fatalf("terminal record reprocessed at the ceiling: %+v", rep.Results)
179		}
180	}
