182	// Reaching the ceiling without coverage evaluates the retry exactly once and
183	// keeps the message waiting with its saturated schedule; every further
184	// equal-time advance neither retries nor re-reports the waiting result.
185	func TestCeilingRetryWithoutCoverageWaitsOnce(t *testing.T) {
186		q, _ := openTempQueue(t)
187		defer q.Close()
188		waitingAtCeilingSetup(t, q, "m1")
189	
190		if _, err := q.Advance(ceiling - 500); err != nil {
191			t.Fatal(err)
192		}
193		// The scheduled retry reaches the ceiling: the message is evaluated once
194		// more and, still uncovered, keeps waiting with attempts=2.
195		rep, err := q.Advance(ceiling)
196		if err != nil {
197			t.Fatal(err)
198		}
199		res, ok := resultFor(rep, "m1")
200		if !ok || res.Status != StatusWaiting {
201			t.Fatalf("at ceiling without coverage: want one waiting result, got %+v", rep.Results)
202		}
203		before := statusOf(t, q, "m1")
204		if before.Status != StatusWaiting || before.Attempts != 2 || before.NextRetry != ceiling {
205			t.Fatalf("want waiting attempts=2 retry=ceiling, got %+v", before)
206		}
207	
208		// Repeated equal-time advances must not attempt again and must not report
209		// another waiting result.
210		for i := 0; i < 3; i++ {
211			rep, err := q.Advance(ceiling)
212			if err != nil {
213				t.Fatal(err)
214			}
215			if len(rep.Results) != 0 {
216				t.Fatalf("equal-time advance %d re-reported waiting: %+v", i+1, rep.Results)
217			}
218			after := statusOf(t, q, "m1")
219			if after.Status != before.Status || after.Reason != before.Reason ||
220				after.Attempts != before.Attempts || after.NextRetry != before.NextRetry {
221				t.Fatalf("equal-time advance %d changed the record: %+v vs %+v", i+1, after, before)
222			}
223		}
