225		// A covering header arriving at the ceiling does not itself process the
226		// message, and an equal-time advance still cannot deliver it: the message
227		// was already processed at the ceiling and waiting rules are not bypassed.
228		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
229			t.Fatal(err)
230		}
231		after := statusOf(t, q, "m1")
232		if after.Status != StatusWaiting || after.Attempts != 2 || after.NextRetry != ceiling {
233			t.Fatalf("header update at the ceiling processed the message: %+v", after)
234		}
235		rep, err = q.Advance(ceiling)
236		if err != nil {
237			t.Fatal(err)
238		}
239		if len(rep.Results) != 0 {
240			t.Fatalf("header at the ceiling bypassed the waiting rules: %+v", rep.Results)
241		}
242		if r := statusOf(t, q, "m1"); r.Status != StatusWaiting {
243			t.Fatalf("message must keep waiting at the ceiling after the header: %+v", r)
244		}
