336	// Stopping repeated attempts at the ceiling must not skip the replay and
337	// expiry checks that apply to every non-terminal message regardless of its
338	// backoff.
339	func TestReplayAndExpiryStillApplyAtCeiling(t *testing.T) {
340		t.Run("stuck waiting message becomes replay", func(t *testing.T) {
341			q, _ := openTempQueue(t)
342			defer q.Close()
343			waitingAtCeilingSetup(t, q, "m1") // nonce 7, uncovered proof 100
344			// m1 first-processes at the ceiling and gets stuck waiting there.
345			if _, err := q.Advance(ceiling); err != nil {
