404	// Close/reopen restores the saturated waiting record and schedule, and the
405	// legal write must not look like corruption on recovery.
406	func TestCeilingWaitingSurvivesRestart(t *testing.T) {
407		dir := t.TempDir()
408		q, err := Open(dir)
409		if err != nil {
410			t.Fatal(err)
411		}
412		waitingAtCeilingSetup(t, q, "m1")
413		if _, err := q.Advance(ceiling - 500); err != nil {
414			t.Fatal(err)
415		}
416		if _, err := q.Advance(ceiling); err != nil { // uncovered: attempts=2, retry=ceiling
417			t.Fatal(err)
418		}
419		if err := q.Close(); err != nil {
420			t.Fatal(err)
421		}
422	
423		q2, err := Open(dir)
424		if err != nil {
425			t.Fatalf("reopen must not report corruption: %v", err)
426		}
427		defer q2.Close()
428		if q2.Now() != ceiling {
429			t.Fatalf("processing time lost: want %d got %d", ceiling, q2.Now())
430		}
431		r := statusOf(t, q2, "m1")
432		if r.Status != StatusWaiting || r.Attempts != 2 || r.NextRetry != ceiling {
433			t.Fatalf("saturated waiting record not restored: %+v", r)
434		}
435		// Equal-time advance after recovery still must not reprocess.
436		rep, err := q2.Advance(ceiling)
437		if err != nil {
438			t.Fatal(err)
439		}
440		if len(rep.Results) != 0 {
441			t.Fatalf("restored message retried at the ceiling: %+v", rep.Results)
442		}
443		if r := statusOf(t, q2, "m1"); r.Attempts != 2 || r.NextRetry != ceiling {
444			t.Fatalf("restored record changed on equal-time advance: %+v", r)
445		}
446	}
447	
448	// Compaction persists the saturated schedule and the compacted snapshot
449	// reopens without corruption.
450	func TestCeilingWaitingSurvivesCompaction(t *testing.T) {
451		dir := t.TempDir()
452		q, err := Open(dir)
453		if err != nil {
454			t.Fatal(err)
455		}
456		waitingAtCeilingSetup(t, q, "m1")
457		if _, err := q.Advance(ceiling - 500); err != nil {
458			t.Fatal(err)
459		}
460		if err := q.store.compact(q.snapshot()); err != nil {
461			t.Fatal(err)
462		}
463		if err := q.Close(); err != nil {
464			t.Fatal(err)
465		}
466		q2, err := Open(dir)
467		if err != nil {
468			t.Fatalf("reopen compacted log at the ceiling: %v", err)
469		}
470		defer q2.Close()
471		r := statusOf(t, q2, "m1")
472		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != ceiling {
473			t.Fatalf("saturated schedule lost in compaction: %+v", r)
474		}
475	}
476	
477	// A log written by an older build that stored the raw overflowed (negative)
478	// retry near the ceiling opens directly: the wrapped value is recognized as
479	// the old scheduler's output, repaired to the saturated ceiling in memory,
480	// and the message keeps waiting without reprocessing at the same time.
481	func TestLegacyOverflowedRetryRepairedOnReopen(t *testing.T) {
482		dir := t.TempDir()
483		now := ceiling
484		wrapped := now + 1000 // old code wrote now+delay even when it wrapped
485		if wrapped >= 0 {
486			t.Fatalf("test setup: expected a negative wrapped retry, got %d", wrapped)
487		}
488		entries := []*logEntry{
489			{T: kindSource, Chain: "a"},
490			{T: kindHeader, Chain: "a", Height: 99, Root: "0x99", Trusted: true},
491			{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 7, ProofAt: 100},
492			{T: kindResult, Now: now, ID: "w", Status: StatusWaiting,
493				Reason:   "waiting for trusted header covering height 100 (current 99)",
494				Attempts: 1, NextRetry: wrapped},
495			{T: kindAdvance, Now: now},
496		}
497		writeLegacyLog(t, dir, entries...)
498	
499		q, err := Open(dir)
500		if err != nil {
501			t.Fatalf("legacy overflowed retry must open and be repaired: %v", err)
502		}
503		defer q.Close()
504		r := statusOf(t, q, "w")
505		if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != ceiling {
506			t.Fatalf("legacy negative retry not repaired to ceiling: %+v", r)
507		}
508		rep, err := q.Advance(ceiling)
509		if err != nil {
510			t.Fatal(err)
511		}
512		if len(rep.Results) != 0 {
513			t.Fatalf("repaired message must not retry at the same time: %+v", rep.Results)
514		}
515		if r := statusOf(t, q, "w"); r.Attempts != 1 || r.NextRetry != ceiling {
516			t.Fatalf("repaired record changed on equal-time advance: %+v", r)
517		}
518	}
519	
520	// Arbitrary malformed waiting schedules near the ceiling are still rejected
521	// as corrupt rather than silently accepted.
522	func TestMalformedCeilingScheduleRejected(t *testing.T) {
523		cases := map[string]int64{
524			"zero retry":     0,
525			"earlier retry":  ceiling - 1,
526			"unrelated time": 42,
527			"positive slack": ceiling - 1000, // canonical is exactly the ceiling
528		}
529		for name, nextRetry := range cases {
530			t.Run(name, func(t *testing.T) {
531				dir := t.TempDir()
532				entries := []*logEntry{
533					{T: kindSource, Chain: "a"},
534					{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 7, ProofAt: 100},
535					{T: kindResult, Now: ceiling, ID: "w", Status: StatusWaiting,
536						Reason: "waiting", Attempts: 1, NextRetry: nextRetry},
537				}
538				writeLegacyLog(t, dir, entries...)
539				q, err := Open(dir)
540				if !errors.Is(err, ErrCorrupt) {
541					if q != nil {
542						q.Close()
543					}
544					t.Fatalf("want ErrCorrupt for nextRetry=%d, got %v", nextRetry, err)
545				}
546			})
547		}
548	}
549	
550	// Negative processing times and backwards moves stay rejected at the ceiling
551	// and change nothing.
552	func TestCeilingRejectsNegativeAndBackwardsTime(t *testing.T) {
553		q, _ := openTempQueue(t)
554		defer q.Close()
555		if _, err := q.Advance(ceiling); err != nil {
556			t.Fatal(err)
557		}
558		if _, err := q.Advance(-1); !errors.Is(err, ErrInvalidArg) {
559			t.Fatalf("negative time at the ceiling: want ErrInvalidArg, got %v", err)
560		}
561		if _, err := q.Advance(ceiling - 1); !errors.Is(err, ErrInvalidArg) {
562			t.Fatalf("backwards time at the ceiling: want ErrInvalidArg, got %v", err)
563		}
564		if q.Now() != ceiling {
565			t.Fatalf("rejected advances changed processing time: %d", q.Now())
566		}
567	}
