			&logEntry{T: kindResult, Now: 16999, ID: "w", Status: StatusWaiting,
				Reason: "waiting", Attempts: 6, NextRetry: 48999},
		)
		assertRecoveryCorrupt(t, entries, "not due under the saved retry schedule", `"w"`)
	})
